local function notify(title, text, dur, kind)
if Core.unloaded then return end
dur = dur or 3
local key, now = tostring(title) .. "|" .. tostring(text), os.clock()
local nl = Core.nl
if nl.last[key] and now - nl.last[key] < 2 then return end
if nl.last[title] and now - nl.last[title] < 0.6 then return end
nl.last[key] = now; nl.last[title] = now
local col = (kind == "danger") and Color3.fromRGB(255, 96, 112) or T.AccentHi
local n = make("CanvasGroup", {BackgroundColor3 = T.PanelHi, Size = UDim2.fromOffset(280, 64), GroupTransparency = 1, ZIndex = 900}, notifHolder)
make("UICorner", {CornerRadius = UDim.new(0, 12)}, n)
stroke(n, col, 1.2, 0.55)
local pill = make("Frame", {BackgroundColor3 = col, Position = UDim2.fromOffset(10, 14), Size = UDim2.fromOffset(4, 36), BorderSizePixel = 0}, n)
make("UICorner", {CornerRadius = UDim.new(1, 0)}, pill)
make("TextLabel", {BackgroundTransparency = 1, Position = UDim2.fromOffset(24, 7), Size = UDim2.new(1, -32, 0, 18),
Text = string.upper(title), FontFace = F_HEAVY, TextSize = 17, TextColor3 = col, TextXAlignment = Enum.TextXAlignment.Left}, n)
make("TextLabel", {BackgroundTransparency = 1, Position = UDim2.fromOffset(24, 26), Size = UDim2.new(1, -32, 0, 28),
Text = text, FontFace = F_BOLD, TextSize = 18, TextColor3 = T.Text, TextXAlignment = Enum.TextXAlignment.Left,
TextYAlignment = Enum.TextYAlignment.Top, TextWrapped = true}, n)
local bar = make("Frame", {BackgroundColor3 = col, BackgroundTransparency = 0.4, Position = UDim2.new(0, 14, 1, -6),
Size = UDim2.new(1, -28, 0, 3), BorderSizePixel = 0}, n)
make("UICorner", {CornerRadius = UDim.new(1, 0)}, bar)
tween(n, 0.25, {GroupTransparency = 0})
tween(bar, dur, {Size = UDim2.new(0, 0, 0, 3)}, Enum.EasingStyle.Linear)
table.insert(nl.live, n)
while #nl.live > 3 do local o = table.remove(nl.live, 1); pcall(function() o:Destroy() end) end
task.delay(dur, function()
if n.Parent then tween(n, 0.25, {GroupTransparency = 1}).Completed:Connect(function() n:Destroy() end) end
end)
end
