local okDice = pcall(function()
local vp = Instance.new("ViewportFrame")
vp.BackgroundTransparency = 1; vp.AnchorPoint = Vector2.new(0, 0.5); vp.Position = UDim2.new(0, 8, 0.5, 0)
vp.Size = UDim2.fromOffset(26, 26); vp.ZIndex = 4
