local function part(size, cf, col, shape)
local pt = Instance.new("Part")
pt.Anchored = true; pt.CanCollide = false; pt.Size = size; pt.CFrame = cf; pt.Color = col
pt.Material = Enum.Material.SmoothPlastic
if shape then pt.Shape = shape end
pt.Parent = model
return pt
end
part(Vector3.new(1, 1, 1), CFrame.new(), Color3.fromRGB(246, 242, 230))
local PIP = Color3.fromRGB(26, 26, 32)
local g = {[1] = {{0, 0}}, [2] = {{-1, 1}, {1, -1}}, [3] = {{-1, 1}, {0, 0}, {1, -1}},
[4] = {{-1, -1}, {-1, 1}, {1, -1}, {1, 1}}, [5] = {{-1, -1}, {-1, 1}, {0, 0}, {1, -1}, {1, 1}},
[6] = {{-1, -1}, {-1, 0}, {-1, 1}, {1, -1}, {1, 0}, {1, 1}}}
local faces = {
{Vector3.new(0, 1, 0), Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), 5},
{Vector3.new(0, -1, 0), Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), 2},
{Vector3.new(0, 0, 1), Vector3.new(1, 0, 0), Vector3.new(0, 1, 0), 3},
{Vector3.new(0, 0, -1), Vector3.new(1, 0, 0), Vector3.new(0, 1, 0), 4},
{Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(0, 1, 0), 1},
{Vector3.new(-1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(0, 1, 0), 6},
}
for _, fc in ipairs(faces) do
local n, u, v = fc[1], fc[2], fc[3]
for _, ab in ipairs(g[fc[4]]) do
local pos = n * 0.495 + u * (ab[1] * 0.26) + v * (ab[2] * 0.26)
local cf = CFrame.lookAt(pos, pos + n) * CFrame.Angles(0, math.pi / 2, 0)
part(Vector3.new(0.03, 0.22, 0.22), cf, fc[4] == 1 and Anim.Gold or PIP, Enum.PartType.Cylinder)
end
end
