base = base + math.pi * 4
tween(nv, 0.95, {Value = base}, Enum.EasingStyle.Quint)
task.delay(0.98, function() rolling = false; if hov then tween(nv, 0.3, {Value = base + 0.6}, Enum.EasingStyle.Quad) end end)
