oname = "", oon = false, odn = "", odon = false, oav = "", oavon = false}
local tr = setmetatable({}, {__mode = "k"})
local busy = false
local function esc(s) return (s:gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%0")) end
local function rep(s) return (s:gsub("%%", "%%%%")) end
local function textOn() return (S.lon and S.lname ~= "") or (S.ldon and S.ldn ~= "") or (S.oon and S.oname ~= "") or (S.odon and S.odn ~= "") end
local function pairList()
    local t = {}
    if S.lon and S.lname ~= "" then t[#t + 1] = {lp.Name, S.lname} end
    if S.ldon and S.ldn ~= "" and lp.DisplayName ~= lp.Name then t[#t + 1] = {lp.DisplayName, S.ldn} end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= lp then
            if S.oon and S.oname ~= "" then t[#t + 1] = {p.Name, S.oname} end
            if S.odon and S.odn ~= "" and p.DisplayName ~= p.Name then t[#t + 1] = {p.DisplayName, S.odn} end
        end
    end
    return t
end
local function conv(txt, list)
    local out = txt
    for _, pr in ipairs(list) do
        if pr[1] ~= "" then out = out:gsub(esc(pr[1]), rep(pr[2])) end
    end
    return out
end
local function isText(o) return o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") end
local function ours(o)
    return (gui and gui:IsAncestorOf(o)) or (HUD and HUD.gui and HUD.gui:IsAncestorOf(o))
end
