    if not desc then pcall(notify, "Spoofer", "Could not load avatar " .. tostring(id), 3, "danger"); return end
    local ok, model = pcall(function() return Players:CreateHumanoidModelFromDescriptionAsync(desc, hum.RigType) end)
    if not ok or not model then pcall(notify, "Spoofer", "Could not build avatar " .. tostring(id), 3, "danger"); return end
    if not char.Parent then model:Destroy(); return end
    local st = {made = {}, stash = {}, colors = {}, madeDecor = {}, stashDecor = {}}
    spoofs[char] = st
    for _, c in ipairs(char:GetChildren()) do
        if c:IsA("BasePart") then st.colors[c] = c.Color
        elseif isAny(c, STASH) then c.Parent = nil; st.stash[c] = true end
