        r = {orig = plr:GetAttribute(attr), writing = false}
        r.conn = plr:GetAttributeChangedSignal(attr):Connect(function()
            if r.writing then return end
            r.orig = plr:GetAttribute(attr)
            r.writing = true; plr:SetAttribute(attr, r.spoof); r.writing = false
        end)
        g[attr] = r
    end
    r.spoof = value
    r.writing = true; plr:SetAttribute(attr, value); r.writing = false
end
