local function canSet() return type(setfflag) == "function" end
local function apply(name, value)
    if not canSet() then pcall(notify, "FFlags", "Your executor has no setfflag", 3.5, "danger"); return false end
    if saved[name] == nil and type(getfflag) == "function" then
