local function hpColor(f) return f > 0.5 and YELLOW:Lerp(GREEN, (f - 0.5) * 2) or RED:Lerp(YELLOW, f * 2) end
local function hideAll(o) o.root.Visible = false; o.tr.Visible = false; if o.td then o.td.Visible = false end end
