local tb, tc = 0, 0
local anyCham = false
local function espStep(dt)
dt = math.min(dt, 0.1)
local cam = Workspace.CurrentCamera
local anyEsp = S.box or S.name or S.hp or S.dist or S.tracer
tb = tb + (dt * S.gspeed); tc = tc + (dt * S.cspeed)
if not cam then return end
if not S.cham and anyCham then
for _, h in pairs(chamObjs) do pcall(function() h:Destroy() end) end
table.clear(chamObjs); anyCham = false
end
if not anyEsp and not S.cham then
for _, o in pairs(objs) do hideAll(o) end
return
end
local camPos = cam.CFrame.Position
for _, plr in ipairs(Players:GetPlayers()) do
if plr ~= player then
local o = objs[plr]
local char = plr.Character
local hrp = char and char:FindFirstChild("HumanoidRootPart")
local head = char and char:FindFirstChild("Head")
local hum = char and char:FindFirstChildOfClass("Humanoid")
local ok = hrp and head and hum and hum.Health > 0
if ok and S.team and plr.Team ~= nil and plr.Team == player.Team then ok = false end
local dist = 0
if ok then dist = (camPos - hrp.Position).Magnitude; if dist > S.maxd then ok = false end end
local hl = chamObjs[plr]
