if not hl or hl.Parent ~= char then
if hl then pcall(function() hl:Destroy() end) end
hl = Instance.new("Highlight"); hl.Name = "AspenCham"; hl.Adornee = char; hl.Parent = char
chamObjs[plr] = hl; anyCham = true
end
hl.Enabled = true
hl.DepthMode = S.walls and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded
hl.OutlineColor = S.chamOut; hl.OutlineTransparency = 0
if S.cfill then
local col, ft = S.chamCol, 0.45
if S.cgrad then
local ph = (o and o.ph) or (plr.UserId % 628) / 100
local p
if S.cmode == "Pulse" then p = 0.5 + 0.5 * math.sin(tc * 3); ft = 0.55 - 0.2 * p
elseif S.cmode == "Wave" then p = 0.5 + 0.5 * math.sin(tc * 2 + dist * 0.08 + ph)
else local fr = (tc * 0.35 + ph) % 1; p = 1 - math.abs(2 * fr - 1) end
col = sampleGrad(S.cA, S.cB, S.cS, S.cE, p)
end
hl.FillColor = col; hl.FillTransparency = ft
else hl.FillTransparency = 1 end
elseif hl then hl.Enabled = false end
local shown = false
if ok and anyEsp then
if not o then o = newObj(plr); objs[plr] = o end
shown = true
local vp = cam.ViewportSize
local cpos = hrp.Position - Vector3.new(0, 0.25, 0)
local c = cam:WorldToViewportPoint(cpos)
local front = c.Z > 0
local h = 0
if front then
local u = cam:WorldToViewportPoint(cpos + cam.CFrame.UpVector * 2.75)
h = math.min(math.sqrt((u.X - c.X) ^ 2 + (u.Y - c.Y) ^ 2) * 2, 3000)
end
if S.tracer then
local org
local oc = S.tracerOrigin
if oc == "Center" then org = Vector2.new(vp.X / 2, vp.Y / 2)
elseif oc == "Top" then org = Vector2.new(vp.X / 2, 0)
elseif oc == "Mouse" then org = game:GetService("UserInputService"):GetMouseLocation()
else org = Vector2.new(vp.X / 2, vp.Y) end
local tx, ty
local inView = false
if front then
tx, ty = c.X, c.Y + h / 2
inView = tx >= 0 and tx <= vp.X and ty >= 0 and ty <= vp.Y
else
local rel = cam.CFrame:PointToObjectSpace(hrp.Position)
local dir = Vector2.new(rel.X, -rel.Y)
if dir.Magnitude < 1e-3 then dir = Vector2.new(0, 1) end
dir = dir.Unit
tx, ty = org.X + dir.X * 4000, org.Y + dir.Y * 4000
end

local dx, dy = tx - org.X, ty - org.Y
local tmax = 1
if dx > 0 then tmax = math.min(tmax, (vp.X - org.X) / dx) elseif dx < 0 then tmax = math.min(tmax, (0 - org.X) / dx) end
if dy > 0 then tmax = math.min(tmax, (vp.Y - org.Y) / dy) elseif dy < 0 then tmax = math.min(tmax, (0 - org.Y) / dy) end
tmax = math.max(tmax, 0)
tx, ty = org.X + dx * tmax, org.Y + dy * tmax
dx, dy = tx - org.X, ty - org.Y
local len = math.sqrt(dx * dx + dy * dy)
if len < 2 then
o.tr.Visible = false; o.td.Visible = false
else
o.tr.Size = UDim2.fromOffset(math.floor(len), S.tracerThick)
o.tr.Position = UDim2.fromOffset((org.X + tx) / 2, (org.Y + ty) / 2)
o.tr.Rotation = math.deg(math.atan2(dy, dx))
o.tr.BackgroundColor3 = S.tracerCol
o.tr.BackgroundTransparency = S.tracerFade and math.clamp(dist / 3000, 0, 1) * 0.7 or 0
o.tr.Visible = true
o.td.Position = UDim2.fromOffset(tx, ty)
o.td.BackgroundColor3 = S.tracerCol
o.td.BackgroundTransparency = inView and 0 or 0.5
o.td.Visible = S.tracerDot
end
else
o.tr.Visible = false; o.td.Visible = false
end
if front and h >= 6 then
local w = h * 0.5
o.root.Position = UDim2.fromOffset(math.floor(c.X - w / 2), math.floor(c.Y - h / 2))
o.root.Size = UDim2.fromOffset(math.floor(w), math.floor(h))
o.root.Visible = true
local full, cor = S.box and S.boxStyle == "Box", S.box and S.boxStyle == "Corner"
o.box.Visible = full; o.outer.Visible = full
if full then o.bs.Color = S.boxCol end
local L = math.max(5, math.floor(math.min(w, h) * 0.3))
for i, fr in ipairs(o.cor) do
fr.Visible = cor
if cor then
fr.BackgroundColor3 = S.boxCol
fr.Size = (i % 2 == 1) and UDim2.fromOffset(L, 2) or UDim2.fromOffset(2, L)
end
end
local showFill = S.box and S.fill
o.fill.Visible = showFill
if showFill then
if S.grad then
o.fill.BackgroundColor3 = WHITE
o.fg.Enabled = true
if o.gv ~= gver then o.gv = gver; o.fg.Color = gradSeq(S.gA, S.gB, S.gS, S.gE) end
local m = S.gmode
if m == "Pulse" then o.fg.Rotation = 90; o.fg.Offset = Vector2.new(0, 0); o.fill.BackgroundTransparency = math.clamp(S.fillT + 0.12 - 0.3 * (0.5 + 0.5 * math.sin(tb * 3 + o.ph)), 0, 1)
elseif m == "Wave" then o.fg.Rotation = 90; o.fg.Offset = Vector2.new(0, math.sin(tb * 2 + o.ph) * 0.5); o.fill.BackgroundTransparency = math.clamp(S.fillT - 0.1, 0, 1)
else o.fg.Rotation = (tb * 120 + o.ph * 57) % 360; o.fg.Offset = Vector2.new(0, 0); o.fill.BackgroundTransparency = math.clamp(S.fillT - 0.1, 0, 1) end
else
o.fg.Enabled = false; o.fill.BackgroundColor3 = S.boxCol; o.fill.BackgroundTransparency = math.clamp(S.fillT + 0.05, 0, 1)
end
end
local now = os.clock()
o.name.Visible = S.name
if S.name then
o.name.Text = plr.DisplayName
o.ng.Enabled = false; o.name.TextColor3 = S.nameCol
end
o.dist.Visible = S.dist
if S.dist then
o.dist.Text = math.floor(dist) .. "m"
o.dg.Enabled = false; o.dist.TextColor3 = S.distCol
end
o.hpBg.Visible = S.hp
if S.hp then
local target = math.clamp(hum.Health / math.max(1, hum.MaxHealth), 0, 1)
o.hp = o.hp + ((target - o.hp) * math.min(1, dt * 9))
o.hpFill.Size = UDim2.new(1, -2, o.hp, -2)
o.hpFill.BackgroundColor3 = hpColor(o.hp)
end
else
o.root.Visible = false
end
end
if o and not shown then hideAll(o) end
end
end
end
