return Workspace:Raycast(from, part.Position - from, rayP) == nil
end
local function holding(char, plr, needle)
for _, c in ipairs(char:GetChildren()) do
if (c:IsA("Tool") or c:IsA("Model")) and string.find(string.lower(c.Name), needle, 1, true) then return true end
end
for _, src in ipairs({char, plr}) do
for _, v in pairs(src:GetAttributes()) do
if type(v) == "string" and string.find(string.lower(v), needle, 1, true) then return true end
end
end
return false
end
local baseFov = 70
local function isScoped(cam)
local f = cam.FieldOfView
if f > baseFov then baseFov = f end
return f < baseFov * 0.9 or UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
end
local randPlr, randPart
local function pickPart(char, plr, cam, origin)
local head = char:FindFirstChild("Head")
local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
local hrp = char:FindFirstChild("HumanoidRootPart")
local sel = A.part
if sel == "Head" then return head
elseif sel == "Torso" then return torso
elseif sel == "HumanoidRootPart" then return hrp
elseif sel == "Random" then
if randPlr ~= plr or not randPart or not randPart.Parent then
local list = {}
for _, q in ipairs({head, torso, hrp}) do if q then list[#list + 1] = q end end
randPlr, randPart = plr, list[math.random(1, math.max(1, #list))]
end
return randPart
end
local best, bd = nil, math.huge
