if q then
local sp = cam:WorldToViewportPoint(q.Position)
local d = (Vector2.new(sp.X, sp.Y) - origin).Magnitude
if sp.Z > 0 and d < bd then best, bd = q, d end
end
end
return best
end

local aimVel, acc, seed = Vector2.zero, Vector2.zero, math.random() * 100
local function stepPx(delta, dt)
local s, mode = A.smooth, A.mode
if mode == "Lock" or s <= 0.001 then aimVel = Vector2.zero; return delta end
local dist = delta.Magnitude
if dist < 0.25 then return Vector2.zero end
if mode == "Linear" then
local speed = 3000 * (1 - s) ^ 2 + 40
return delta.Unit * math.min(dist, speed * dt)
elseif mode == "Spring" then
dt = math.min(dt, 1 / 30)
local k = 600 * (1 - s) ^ 2 + 20
local d = 2 * math.sqrt(k) * 0.55
aimVel = aimVel + (delta * k - aimVel * d) * dt
return aimVel * dt
end
local f = 0.02 + 0.45 * (1 - s) ^ 2
local a = 1 - (1 - f) ^ (dt * 60)
local now = os.clock()
local perp = Vector2.new(-delta.Y, delta.X).Unit
local curve = perp * math.sin(now * 6 + seed) * math.min(dist, 200) * 0.12 * a
local jit = Vector2.new(math.noise(now * 3, seed), math.noise(seed, now * 3)) * math.min(dist, 8) * 0.3
return delta * a + curve + jit * a
end
local camCtl, camSet
task.spawn(function()
pcall(function()
local ps = player:WaitForChild("PlayerScripts", 15)
local ctrls = ps and ps:WaitForChild("Controllers", 15)
local mod = ctrls and ctrls:WaitForChild("CameraController", 15)
local ctl = mod and require(mod)
if type(ctl) ~= "table" then return end
local mt = getmetatable(ctl)
local idx = mt and rawget(mt, "__index")
local fn = (type(idx) == "table" and rawget(idx, "SetRotation")) or ctl.SetRotation
if type(fn) == "function" then camCtl, camSet = ctl, fn end
end)
end)
local function getRot()
if not camCtl then return nil end
local ok, r = pcall(rawget, camCtl, "Rotation")
if ok and typeof(r) == "Vector2" then return r end
ok, r = pcall(function() return camCtl.Rotation end)
if ok and typeof(r) == "Vector2" then return r end
return nil
end
local function setRot(v)
if camCtl and camSet then coroutine.wrap(camSet)(camCtl, v) end
end
local function resolveMethod()
local m = A.method
if m == "Game Rotation" then
if camCtl and camSet then return m end
return (type(mousemoverel) == "function") and "Mouse" or "Camera"
end
if m == "Mouse" and type(mousemoverel) ~= "function" then return "Camera" end
return m
end
local function aimOrigin(cam, vp, forceRot)
if forceRot or resolveMethod() == "Game Rotation" then
local r = getRot()
if r then
local p = cam:WorldToViewportPoint(cam.CFrame.Position + CFrame.fromOrientation(r.X, r.Y, 0).LookVector * 1000)
if p.Z > 0 then return Vector2.new(p.X, p.Y) end
end
end
return (UIS.MouseBehavior == Enum.MouseBehavior.LockCenter) and Vector2.new(vp.X / 2, vp.Y / 2) or UIS:GetMouseLocation()
end
local function applyMove(move, cam, vp)
local m = resolveMethod()
if m == "Mouse" then
acc = acc + move * A.gain
local ix = acc.X >= 0 and math.floor(acc.X) or math.ceil(acc.X)
local iy = acc.Y >= 0 and math.floor(acc.Y) or math.ceil(acc.Y)
if ix ~= 0 or iy ~= 0 then
acc = acc - Vector2.new(ix, iy)
pcall(mousemoverel, ix, iy)
end
elseif m == "Game Rotation" then
local apx = 2 * math.tan(math.rad(cam.FieldOfView) / 2) / math.max(1, vp.Y)
local r = getRot()
if r then
setRot(Vector2.new(math.clamp(r.X - math.atan(move.Y * apx), -1.5, 1.5), r.Y - math.atan(move.X * apx)))
end
else
local apx = 2 * math.tan(math.rad(cam.FieldOfView) / 2) / math.max(1, vp.Y)
local cf = cam.CFrame
local rot = cf - cf.Position
rot = CFrame.Angles(0, -move.X * apx, 0) * rot
cam.CFrame = (CFrame.new(cf.Position) * rot) * CFrame.Angles(-move.Y * apx, 0, 0)
end
end

local function frame(dt)
local cam = Workspace.CurrentCamera
if not cam then ring.Visible = false; return end
local vp = cam.ViewportSize
local origin = aimOrigin(cam, vp)
