local m = A.fmode
if m == "Pulse" then fillGrad.Rotation = 90; fillGrad.Offset = Vector2.zero; ringFill.BackgroundTransparency = math.clamp(A.fillT + 0.12 - 0.3 * (0.5 + 0.5 * math.sin(tf * 3)), 0, 1)
elseif m == "Wave" then fillGrad.Rotation = 90; fillGrad.Offset = Vector2.new(0, math.sin(tf * 2) * 0.5); ringFill.BackgroundTransparency = math.clamp(A.fillT - 0.1, 0, 1)
else fillGrad.Rotation = (tf * 120) % 360; fillGrad.Offset = Vector2.zero; ringFill.BackgroundTransparency = math.clamp(A.fillT - 0.1, 0, 1) end
ringGrad.Rotation = fillGrad.Rotation
else
fillGrad.Enabled = false; ringGrad.Enabled = false
ringFill.BackgroundColor3 = A.fovCol; ringFill.BackgroundTransparency = math.clamp(A.fillT + 0.1, 0, 1)
end
else
fillGrad.Enabled = false; ringGrad.Enabled = false
end
else
ring.Visible = false
end
if not active() then aimVel = Vector2.zero; acc = Vector2.zero; randPlr = nil; return end
local conds = {}
for _, c in ipairs(CONFIG_VALUES[condKey] or {}) do conds[c] = true end
if conds["Scoped Only"] and not isScoped(cam) then aimVel = Vector2.zero; return end
local best, bestPart, bestD = nil, nil, A.radius
local camPos = cam.CFrame.Position
for _, plr in ipairs(Players:GetPlayers()) do
if plr ~= player then
local char = plr.Character
local hum = char and char:FindFirstChildOfClass("Humanoid")
local hrp = char and char:FindFirstChild("HumanoidRootPart")
if hum and hrp and hum.Health > 0 and not (S.team and plr.Team ~= nil and plr.Team == player.Team)
and (camPos - hrp.Position).Magnitude <= S.maxd
and not (conds["Not Katana"] and holding(char, plr, "katana"))
and not (conds["Not Riot Shield"] and holding(char, plr, "riot")) then
local part = pickPart(char, plr, cam, origin)
if part then
local sp = cam:WorldToViewportPoint(part.Position)
