function SA.visible(cam, part, char)
local ign = {player.Character, char, cam}
local from = cam.CFrame.Position
local dir = part.Position - from
for _ = 1, 16 do
saRP.FilterDescendantsInstances = ign
local r = Workspace:Raycast(from, dir, saRP)
if not r then return true end
local h = r.Instance
if h:IsDescendantOf(char) then return true end
if h.CanCollide == false or h.Transparency >= 0.95 then
ign[#ign + 1] = h
else
return false
end
end
return false
end
function SA.pick(cam, origin)
local conds = {}
for _, c in ipairs(CONFIG_VALUES[SA.condKey] or {}) do conds[c] = true end
if conds["Scoped Only"] and not isScoped(cam) then return nil end
local best, bestPart, bestD, bestSp = nil, nil, SA.radius, nil
local camPos = cam.CFrame.Position
for _, plr in ipairs(Players:GetPlayers()) do
if plr ~= player then
local char = plr.Character
local hum = char and char:FindFirstChildOfClass("Humanoid")
local hrp = char and char:FindFirstChild("HumanoidRootPart")
if hum and hrp and hum.Health > 0 and not (S.team and plr.Team ~= nil and plr.Team == player.Team)
and (camPos - hrp.Position).Magnitude <= S.maxd
and not (conds["Not Katana"] and holding(char, plr, "katana"))
and not (conds["Not Riot Shield"] and holding(char, plr, "riot")) then
for _, q in ipairs(SA.parts(char, plr, SA.part)) do
local sp = cam:WorldToViewportPoint(q.Position)
if sp.Z > 0 then
local v2 = Vector2.new(sp.X, sp.Y)
local d = (v2 - origin).Magnitude
if d < bestD and (not conds["Visible"] or SA.visible(cam, q, char)) then best, bestPart, bestD, bestSp = plr, q, d, v2 end
end
end
end
end
end
return best, bestPart, bestSp
end

local function cfEnc(cf)
local rx, ry, rz = cf:ToOrientation()
return {["\0"] = cf.X, ["\1"] = cf.Y, ["\2"] = cf.Z, ["\3"] = rx, ["\4"] = ry, ["\5"] = rz}
end
local function cfDec(t)
if type(t) ~= "table" then return nil end
local a, b, c, d, e, f = t["\0"], t["\1"], t["\2"], t["\3"], t["\4"], t["\5"]
if type(a) ~= "number" or type(b) ~= "number" or type(c) ~= "number" or type(d) ~= "number" or type(e) ~= "number" or type(f) ~= "number" then return nil end
return CFrame.new(a, b, c) * CFrame.fromOrientation(d, e, f)
end
local hitRP = RaycastParams.new()
hitRP.FilterType = Enum.RaycastFilterType.Include
local function hitLocal(from, part, tp)
hitRP.FilterDescendantsInstances = {part}
local r = Workspace:Raycast(from, tp - from, hitRP)
if not r then return nil end
local l = part.CFrame:PointToObjectSpace(r.Position)
if l == Vector3.zero then return nil end
return l
end
local function targetPoint(part)
if SA.point == "Random" then
local h = part.Size * 0.3
return part.CFrame:PointToWorldSpace(Vector3.new((math.random() * 2 - 1) * h.X, (math.random() * 2 - 1) * h.Y, (math.random() * 2 - 1) * h.Z))
end
return part.Position
end
SA.mm = {back = false, range = false, rangeV = 10}
local function meleeMods(nm, args)
local mm = SA.mm
if not (mm.back or mm.range) then return end
if nm ~= "StartShooting" and nm ~= "StartAiming" then return end
if not (SA.meleeEquipped and SA.meleeEquipped()) then return end
local sh = type(args) == "table" and args["\1"]
if type(sh) ~= "table" then return end
local o0 = cfDec(sh["\0"])
if not o0 then return end
local best, bd
local lim = mm.range and mm.rangeV or 20
for _, p in ipairs(Players:GetPlayers()) do
if p ~= player then
local c = p.Character
local h = c and c:FindFirstChildOfClass("Humanoid")
local rt = c and c:FindFirstChild("HumanoidRootPart")
if h and rt and h.Health > 0 then
local d = (rt.Position - o0.Position).Magnitude
if d < lim and (not bd or d < bd) then best, bd = rt, d end
end
end
end
if not best then return end
local pos = mm.range and best.Position or o0.Position
local ori = mm.back and (best.CFrame - best.Position) or CFrame.fromOrientation(-math.pi / 2, 0, 0)
local cf = cfEnc(CFrame.new(pos) * ori)
sh["\0"], sh["\1"] = cf, cf
end
function SA.onShot(encType, args)
do
local fe0 = SA.fromEnum
local nm0 = fe0 and rawget(fe0, encType)
if nm0 then pcall(meleeMods, nm0, args) end
end
local rbp = SA.rb and SA.rbPart
if rbp and not rbp.Parent then rbp = nil end
if SA.dead or (not rbp and not SA.active()) then return end
local fe = SA.fromEnum
if not fe then return end
local nm = rawget(fe, encType)
if nm == nil then local o, v = pcall(function() return fe[encType] end); nm = o and v or nil end
if nm ~= "StartShooting" then return end
if type(args) ~= "table" or SA.done[args] then return end
if not rbp and SA.chance < 100 and math.random() * 100 > SA.chance then return end
local sh = args["\1"]
if type(sh) ~= "table" then return end
local o0, o1 = cfDec(sh["\0"]), cfDec(sh["\1"])
if not o0 or not o1 then return end
local cam = Workspace.CurrentCamera
if not cam then return end
SA.rs.plr = nil
local part = rbp
if not part then local _; _, part = SA.pick(cam, aimOrigin(cam, cam.ViewportSize, true)) end
if not part then return end
local tp = rbp and part.Position or targetPoint(part)
local lh = hitLocal(o0.Position, part, tp)
if not lh then
local l2 = part.CFrame:PointToObjectSpace(part:GetClosestPointOnSurface(o0.Position))
if l2 == Vector3.zero then return end
lh = l2
end
SA.done[args] = true
sh["\0"], sh["\1"], sh["\2"], sh["\3"] = cfEnc(CFrame.lookAt(o0.Position, tp)), cfEnc(CFrame.lookAt(o1.Position, tp)), part, cfEnc(CFrame.new(lh))
end

