return root
end
local function isRS(v) return typeof(v) == "Instance" and ((compareinstances and compareinstances(v, RS)) or v == RS) end
local kinds = {}
local ok, err = pcall(function()
local ClientItem = require(path(player, "PlayerScripts", "Modules", "ClientReplicatedClasses", "ClientFighter", "ClientItem"))
local EnumLib = require(path(RS, "Modules", "EnumLibrary"))
SA.fromEnum = rawget(EnumLib, "_from_enum") or EnumLib._from_enum
