if type(input) ~= "function" then local o, v = pcall(function() return ClientItem.Input end); input = o and v or nil end
if type(input) == "function" and debug and type(debug.getupvalues) == "function" then
local fake = {Remotes = {Replication = {Fighter = {UseItem = {FireServer = function(_, objId, encType, args, ...)
if not SA.dead then pcall(SA.note, objId, encType, args); if SA.on or SA.modsOn then pcall(SA.onShot, encType, args) end
if SA.modsOn and SA.mods then pcall(SA.mods, objId, encType, args) end end
return rawFire(useItem, objId, encType, args, ...)
end}}}}}
local function scan(fn, depth)
for _, up in pairs(debug.getupvalues(fn)) do
if type(up) == "table" then
for k, v in pairs(up) do
if isRS(v) then
up[k] = fake
SA.hooked = {kind = "upvalue", tbl = up, key = k, orig = v}
kinds[#kinds + 1] = "upvalue"
return true
end
end
elseif type(up) == "function" and depth < 2 then
if scan(up, depth + 1) then return true end
end
end
return false
end
pcall(scan, input, 1)
end

if type(hookmetamethod) == "function" and type(getnamecallmethod) == "function" then
local old
old = hookmetamethod(game, "__namecall", (newcclosure or function(f) return f end)(function(self, ...)
if not SA.dead and self == useItem and getnamecallmethod() == "FireServer" and not (checkcaller and checkcaller()) then
local objId, encType, args = ...
pcall(SA.note, objId, encType, args)
if SA.on or SA.modsOn then pcall(SA.onShot, encType, args) end
if SA.modsOn and SA.mods then pcall(SA.mods, objId, encType, args) end
end
return old(self, ...)
end))
SA.hooked = SA.hooked or {kind = "namecall"}
kinds[#kinds + 1] = "namecall"
end
if not SA.hooked then error("no hook method available in this executor") end
end)
SA.installing = false
if SA.hooked then
if not quiet then notify("Silent Aim", "Hook ready (" .. table.concat(kinds, " + ") .. ")", 2.5, "ok") end
else notify("Silent Aim", "Hook failed: " .. tostring(err), 5, "danger") end
end

