local BLACK = Color3.new(0, 0, 0)
local rvRoot = mk("Frame", {Name = "AspenRageVisuals", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Visible = false, ZIndex = 3}, aimGui)
