local rvT, rvFp, rvCp = 0, nil, nil
local function rvTargetPos(cam)
local sp = SA.tScreen
if not sp then
local rt = Core.rbTarget and Core.rbTarget()
if rt and rt.head then local v, on = cam:WorldToViewportPoint(rt.head.Position); if on then sp = Vector2.new(v.X, v.Y) end end
end
return sp
end
local function rvSmooth(cur, goal, dt)
if not cur then return goal end
if (goal - cur).Magnitude <= 5 then return goal end
return cur:Lerp(goal, 1 - math.exp(-dt * 20 / 2))
end
local function rvFrame(dt)
local cam = Workspace.CurrentCamera
local show = RB.on and not RB.dead and cam ~= nil
rvRoot.Visible = show
if not show then rvFp, rvCp = nil, nil; return end
rvT = rvT + (dt * RV.fovSpd)
local c = cam.ViewportSize / 2
local tp = (RV.fFollow or RV.xFollow) and rvTargetPos(cam) or nil
local fc, xc = c, c
if RV.fFollow and tp then rvFp = rvSmooth(rvFp, tp, dt); fc = rvFp else rvFp = nil end
if RV.xFollow and tp then rvCp = rvSmooth(rvCp, tp, dt); xc = rvCp else rvCp = nil end
rvRing.Visible = RV.fov
rvOut.Visible = RV.fov and RV.outl
if RV.fov then
local r = RV.fovR
if RV.scale then r = r * math.tan(math.rad(35)) / math.tan(math.rad(math.clamp(cam.FieldOfView, 5, 170) / 2)) end
local pos = UDim2.fromOffset(math.round(fc.X), math.round(fc.Y))
local sz = UDim2.fromOffset(math.round(r * 2), math.round(r * 2))
rvRing.Position = pos; rvRing.Size = sz
rvOut.Position = pos; rvOut.Size = sz
rvStroke.Thickness = RV.fovTh
rvStroke.Transparency = RV.fovT
rvOutStroke.Thickness = RV.fovTh + 2
rvOutStroke.Transparency = math.clamp(RV.fovT + 0.35, 0, 1)
if RV.wave then
if RV.gv ~= RV.ver then
RV.gv = RV.ver
local seq = ColorSequence.new({ColorSequenceKeypoint.new(0, RV.fovA), ColorSequenceKeypoint.new(0.5, RV.fovB), ColorSequenceKeypoint.new(1, RV.fovA)})
rvGrad.Color = seq; rvFillGrad.Color = seq
end
rvStroke.Color = WHITE
rvGrad.Enabled = true
rvGrad.Rotation = (rvT * 45) % 360
rvGrad.Offset = Vector2.new(math.sin(rvT * 2) * 0.5, 0)
rvFillGrad.Enabled = true
rvFill.BackgroundColor3 = WHITE
rvFillGrad.Rotation = rvGrad.Rotation
rvFillGrad.Offset = rvGrad.Offset
else
rvGrad.Enabled = false; rvFillGrad.Enabled = false
rvStroke.Color = RV.fovA; rvFill.BackgroundColor3 = RV.fovA
end
rvFill.Visible = RV.fill
rvFill.BackgroundTransparency = RV.fillT
end
rvXh.Visible = RV.xh
if RV.xh then
rvXh.Position = UDim2.fromOffset(math.round(xc.X), math.round(xc.Y))
if RV.spin then RV.ang = (RV.ang + dt * RV.spinSpd) % 360 else RV.ang = 0 end
rvXh.Rotation = RV.ang
local L, G, Th = RV.len, RV.gap, RV.th
local mid = G + L / 2
rvBars[1].Size = UDim2.fromOffset(Th, L); rvBars[1].Position = UDim2.fromOffset(0, -mid)
rvBars[2].Size = UDim2.fromOffset(Th, L); rvBars[2].Position = UDim2.fromOffset(0, mid)
rvBars[3].Size = UDim2.fromOffset(L, Th); rvBars[3].Position = UDim2.fromOffset(-mid, 0)
rvBars[4].Size = UDim2.fromOffset(L, Th); rvBars[4].Position = UDim2.fromOffset(mid, 0)
for i = 1, 4 do
rvBars[i].BackgroundColor3 = RV.col
rvBarStrokes[i].Enabled = RV.xOut; rvBarStrokes[i].Thickness = RV.xOutTh
end
rvDot.Visible = RV.dot
rvDot.BackgroundColor3 = RV.col
rvDotStroke.Enabled = RV.xOut; rvDotStroke.Thickness = RV.xOutTh
end
local isText = RV.lblType == "Text"
rvText.Visible = RV.lbl and isText
rvLogo.Visible = RV.lbl and not isText and LOGO_ID ~= nil
local lp = UDim2.fromOffset(math.round(xc.X), math.round(xc.Y + RV.lblOff))
rvText.Position = lp
if rvText.Visible then
rvText.Text = RV.txt; rvText.TextSize = RV.txtSize; rvText.TextColor3 = RV.lblCol
rvText.FontFace = Core.fontOf(RV.font)
rvTextStroke.Enabled = RV.txtOut
end
rvLogo.Position = lp; rvLogo.Size = UDim2.fromOffset(RV.logoSize, RV.logoSize * 0.8)
end
