local function rgMatches(i)
local b = rgKey.Get()
if not b or b == "None" then return false end
return (i.UserInputType == Enum.UserInputType.Keyboard and i.KeyCode.Name == b) or i.UserInputType.Name == b
end
track(UIS.InputBegan:Connect(function(i, gp)
if gp or not rgMatches(i) then return end
RB.held = true; RB.toggled = not RB.toggled
end))
track(UIS.InputEnded:Connect(function(i) if rgMatches(i) then RB.held = false end end))
local function rbActive()
if not RB.on then return false end
if RB.act == "Always" then return true end
if RB.act == "Hold" then return RB.held end
return RB.toggled
end

local FC
local function myFighter()
if not FC then
local ok, m = pcall(function()
local c = player:WaitForChild("PlayerScripts", 3):WaitForChild("Controllers", 3):WaitForChild("FighterController", 3)
return require(c)
end)
FC = ok and m or nil
end
local objs = FC and rawget(FC, "Objects")
if type(objs) ~= "table" then return nil end
for _, o in pairs(objs) do
if type(o) == "table" and rawget(o, "Player") == player then return o end
end
end

Core.myFighter = myFighter
SA.meleeEquipped = function()
local f = myFighter()
local eq = f and rawget(f, "EquippedItem")
local info = type(eq) == "table" and rawget(eq, "Info")
return type(info) == "table" and info.Type == "Melee"
end
local function weaponList(f)
local list, gi = {}, 0
local its = rawget(f, "Items")
if type(its) ~= "table" then return list end
for _, it in pairs(its) do
local info, data = rawget(it, "Info"), rawget(it, "Data")
if type(info) == "table" and type(data) == "table" and data.ObjectID then
local slot
if info.Type == "Melee" then slot = "Melee"
elseif info.Type == "Throwable" then slot = "Utility"
else
gi = gi + 1
slot = tostring(info.Slot or info.Category or "")
if slot ~= "Primary" and slot ~= "Secondary" then slot = gi == 1 and "Primary" or "Secondary" end
end
list[#list + 1] = {item = it, id = data.ObjectID, name = data.Name, ty = info.Type, slot = slot, ammo = data.Ammo, reserve = data.AmmoReserve, ray = info.IsRaycast, info = info}
end
end
return list
end


local function pickTarget(hum, hrp)
local best, bs
for _, plr in ipairs(Players:GetPlayers()) do
if plr ~= player and not (S.team and plr.Team ~= nil and plr.Team == player.Team) then
local c = plr.Character
local h = c and c:FindFirstChildOfClass("Humanoid")
local r = c and c:FindFirstChild("HumanoidRootPart")
local head = c and c:FindFirstChild("Head")
if h and r and head and h.Health > 0 then
local d = (r.Position - hrp.Position).Magnitude
if d <= S.maxd and not (RB.lead and hum.Health < h.Health) then
local score = d
if RB.tprio == "Lowest Health" then score = h.Health * 1000 + d
elseif RB.tprio == "Highest Health" then score = -h.Health * 1000 + d
elseif RB.tprio == "Fastest" then score = -r.AssemblyLinearVelocity.Magnitude * 1000 + d end
if RB.hackers and r.AssemblyLinearVelocity.Magnitude > 120 then score = score - 1e9 end
if not bs or score < bs then best, bs = {plr = plr, char = c, hum = h, root = r, head = head, dist = d}, score end
end
end
end
end
return best
end


function RB.voidPos(p)
local fh = RB.physH
if not (type(fh) == "number" and fh == fh) then fh = -500 end
if fh > -1e7 then p = Vector3.new(p.X, math.max(p.Y, fh + 60), p.Z) end
return CFrame.new(p)
end
local function evadeCF(hrp, t, base)
local now = os.clock()
local m = RB.evade
RB.atk = true; RB.noPark = false; RB.stay = false; RB.jumpTh = 3
if m == "Off" or not t then RB.vsPhase = nil; RB.tcVec = nil; return nil end
RB.noPark = true
local hp = t.head.Position
local bp = (base and base.Position) or hp
local holding = now < RB.shotAt + RB.hold
if m == "Random" then
if now >= RB.rndNext and not holding then
RB.rndNext = now + RB.rndInt
local pool = (RB.curWp or RB.weapon) == "Melee" and {"Void Spam"} or {"Translocate", "Void Spam", "Orbit"}
local pick = pool[math.random(#pool)]
if pick ~= RB.rndPick then RB.vsPhase = nil; RB.tcVec = nil end
RB.rndPick = pick
end
m = RB.rndPick or "Translocate"
end
if m == "Void Spam" then

if not RB.vsPhase then RB.vsPhase = "void"; RB.vsUntil = now + RB.vsWait end
if RB.vsPhase == "void" then
if now >= RB.vsUntil and RB.wpReady ~= false then RB.vsPhase = "up"; RB.vsUpAt = now end
else
local up = now - RB.vsUpAt
local shot = RB.shotAt >= RB.vsUpAt
local leave
if shot then leave = up >= RB.vsUp and now >= RB.shotAt + RB.hold
else leave = up >= RB.vsUp + 0.6 end
if leave then RB.vsPhase = "void"; RB.vsUntil = now + RB.vsWait end
end
if RB.vsPhase == "up" then return CFrame.new(bp) end
RB.atk = false; RB.stay = true
return RB.voidPos(bp - Vector3.new(0, RB.vsDepth, 0))
elseif m == "Translocate" then

if (now >= RB.tcNext and not holding) or not RB.tcVec then
RB.tcNext = now + RB.tcInt
local dirs = {"Left", "Right", "Up", "Down"}
local total, w = 0, {}
for i, d in ipairs(dirs) do w[i] = (d == RB.tcLast) and 0.04 or 1; total = total + (w[i]) end
local r, pick = math.random() * total, dirs[1]
for i, d in ipairs(dirs) do r = r - (w[i]); if r <= 0 then pick = d; break end end
RB.tcLast = pick
local right = t.root.CFrame.RightVector
local D = RB.tcDist
if pick == "Left" then RB.tcVec = -right * D
elseif pick == "Right" then RB.tcVec = right * D
elseif pick == "Up" then RB.tcVec = Vector3.new(0, D, 0)
else RB.tcVec = Vector3.new(0, -D, 0) end
end
return CFrame.new(hp + RB.tcVec)
elseif m == "Orbit" then

RB.jumpTh = 30
local a = now * math.rad(RB.orSpd)
return CFrame.new(hp + Vector3.new(math.cos(a) * RB.orR, RB.orH, math.sin(a) * RB.orR))
end
return nil
end

local function shotCF(origin, part)
local lh = hitLocal(origin, part, part.Position)
if not lh then
local l2 = part.CFrame:PointToObjectSpace(part:GetClosestPointOnSurface(origin))
if l2 == Vector3.zero then return nil end
lh = l2
end
return lh
end

local function fireGun(w, t, cam, org)
local to = SA.toEnum
if not (SA.rawFire and SA.useItem and to) then return false end
local origin = org or cam.CFrame.Position
local lh = shotCF(origin, t.head) or Vector3.zero
local cf = cfEnc(CFrame.lookAt(origin, t.head.Position))
local sh = {["\0"] = cf, ["\1"] = cf, ["\2"] = t.head, ["\3"] = cfEnc(CFrame.new(lh))}
local ray = w.ray
if ray == nil then ray = SA.lastRay end
local args = ray and {["\1"] = sh, ["\2"] = true} or {["\1"] = sh}
SA.rawFire(SA.useItem, w.id, to["StartShooting"], args, nil)
return true
end

local function attackMelee(w, t, cam, org)
local to = SA.toEnum
if not RB.atk then return false end
if not (SA.rawFire and SA.useItem and to) then return false end
local now = tick()
local origin = org or cam.CFrame.Position
local part = t.head
local lh = shotCF(origin, part) or Vector3.zero
local cf
if RB.kr then
local rr = t.root.CFrame
cf = cfEnc(CFrame.new(origin) * (rr - rr.Position))
else cf = cfEnc(CFrame.lookAt(origin, part.Position)) end
local sh = {["\0"] = cf, ["\1"] = cf, ["\2"] = part, ["\3"] = cfEnc(CFrame.new(lh))}
if w.name == "Knife" then

if now < RB.hitUntil then
if now < RB.hitNext then return false end
RB.hitNext = now + 0.06
elseif now < RB.nextMelee then return false
else
RB.hitUntil = now + 0.625
RB.nextMelee = now + RB.mKnifeDelay
RB.hitNext = now + 0.06
end
SA.rawFire(SA.useItem, w.id, to["StartAiming"], {["\1"] = sh, ["\2"] = to["HeavyAttackAnimation1"] or to["HeavyAttack1"]}, nil)
else
if now < RB.nextMelee then return false end
local n = RB.mAlt and RB.mAnim or 1
local an = to["AttackAnimation" .. n] or to["Attack" .. n] or to["AttackAnimation1"] or to["Attack1"]
SA.rawFire(SA.useItem, w.id, to["StartShooting"], {["\1"] = sh, ["\2"] = an}, nil)
RB.mAnim = RB.mAnim % 3 + 1
if not (to["AttackAnimation" .. RB.mAnim] or to["Attack" .. RB.mAnim]) then RB.mAnim = 1 end
RB.nextMelee = now + RB.mDelay
end
return true
end

local function reload(w)
local to = SA.toEnum
local now = tick()
if now < RB.nextReload or not (to and SA.rawFire) then return end
RB.nextReload = now + 0.7
local r = to["Reload"]
SA.rawFire(SA.useItem, w.id, to["StartReloading"], {["\1"] = r, ["\2"] = r}, nil)
return true
end

local function equip(w)
local now = tick()
if now < RB.nextEquip then return end
RB.nextEquip = now + 0.12
pcall(function() local fn = w.item.Equip; if type(fn) == "function" then fn(w.item) end end)
end

local function shootBase(t, now)
local hp = t.head.Position
local mode = RB.spMode
if mode == "Random" then
if RB.spPick and RB.spRoll > 0 and now >= RB.spRoll then RB.spPick = nil; RB.spRoll = 0 end
if not RB.spPick or RB.spTgt ~= t.plr then RB.spPick = math.random(2) == 1 and "Above" or "Inside"; RB.spTgt = t.plr; RB.spRoll = 0 end
mode = RB.spPick
end
if mode == "Above" then return CFrame.new(hp + Vector3.new(0, RB.height, 0)) end
return CFrame.new(hp + Vector3.new(0, -0.7, 0.05))
end

local function resetTarget() RB.tgt = nil; RB.tgtPlr = nil; RB.since = 0 end


local function utKindOk(w)
local n = tostring(w.name or ""):lower()
if n:find("smoke") or n:find("flash") then return RB.utSup end
return RB.utDmg
end

local function utilsSpent(list)
local U = RB.ut
if U and U.phase then return false end
for _, c in ipairs(list) do
if c.slot == "Utility" and utKindOk(c) then
local a, r = c.ammo, c.reserve
if type(a) ~= "number" or a > 0 or (type(r) == "number" and r > 0) then return false end
end
end
return true
end
function RB.utilStep(fighter, list, eqId, t, hrp, cam, now)
local U = RB.ut
if not t then U.phase = nil; U.w = nil; return nil end
local to = SA.toEnum
if not (to and SA.rawFire and SA.useItem) then return nil end
local w
if U.phase and U.w then w = U.w
else
for _, c in ipairs(list) do
if c.slot == "Utility" and utKindOk(c) then
local cd = rawget(c.item, "_throw_cooldown")
if type(cd) ~= "number" or tick() >= cd then w = c; break end
end
end
end
if not w then return nil end
if eqId ~= w.id then equip(w); U.phase = nil; return nil end
local inner = w.item
if not U.phase then
local ok = pcall(inner.Input, inner, "StartShooting")
if not ok then return nil end
U.phase = "hold"; U.w = w; U.t0 = tick()
return nil
end
if U.phase == "hold" then
local cook = (type(w.info) == "table" and rawget(w.info, "CanCook")) and RB.utCook or 0
if tick() - U.t0 >= math.max(RB.utHold, cook) then U.phase = "place"; U.pAt = now end
if tick() - U.t0 > 12 then U.phase = nil; U.w = nil end
return nil
end
local pos = t.head.Position + Vector3.new(0, RB.utHeight, 0)
local plan = CFrame.new(pos)
hrp.CFrame = plan
pcall(function() cam.CFrame = CFrame.lookAt(pos + Vector3.new(0, 1, 0), t.head.Position) end)
if now - U.pAt >= RB.settle then
local ok, name, a, b, c = pcall(inner.FinishShooting, inner, false)
if ok and name ~= nil then
local code = to[name]
if code ~= nil then
SA.rawFire(SA.useItem, w.id, code, {["\0"] = a, ["\1"] = b, ["\2"] = c}, nil)
RB.shotAt = now; RB.lockUntil = now + RB.hold; RB.cycDone = true
end
end
U.phase = nil; U.w = nil
end
return plan
end


local function physSync(on)
if RB.physOn == on then return end
RB.physOn = on
pcall(function()
if on then
if RB.physH == nil then RB.physH = Workspace.FallenPartsDestroyHeight end
Workspace.FallenPartsDestroyHeight = 0 / 0
elseif RB.physH ~= nil then
Workspace.FallenPartsDestroyHeight = RB.physH
end
end)
local sf = setfflag or (syn and syn.setfflag)
if type(sf) == "function" then
pcall(sf, "DFIntS2PhysicsSenderRate", on and "120" or "15")
pcall(sf, "DFIntAssemblyHistoryBufferSize", on and "2147483648" or "15")
pcall(sf, "DFIntAssemblyHistorySkipSize", on and "0" or "8")
end
end

function RB.encAng(a)
if a ~= a then return utf8.char(0) end
return utf8.char(math.clamp(math.floor(a % math.tau / math.pi / 2 * 256 + 0.5), 0, 255))
end
function RB.encRot(v) return RB.encAng(v.X) .. RB.encAng(v.Y) end
function RB.viewHook()
if RB.vhk ~= nil then return RB.vhk end
if not FC then return false end
RB.vhk = false
pcall(function()
local mt = getmetatable(FC)
local proto = mt and rawget(mt, "__index")
local loop = type(proto) == "table" and rawget(proto, "_CameraReplicationLoop")
if type(loop) ~= "function" or not (debug and debug.getupvalues and debug.setupvalue) then return end
for k, up in pairs(debug.getupvalues(loop)) do
if type(up) == "table" then
local m2 = getmetatable(up)
local ix = m2 and rawget(m2, "__index")
if type(ix) == "table" and type(rawget(ix, "EncodeCameraRotation")) == "function" then
local orig = rawget(ix, "EncodeCameraRotation")
debug.setupvalue(loop, k, {EncodeCameraRotation = function(self, rot)
if RB.viewOn then
rawset(FC, "_replication_stopped", false)
return rawget(FC, "_last_encoded_camera_rotation") or orig(self, rot)
end
return orig(self, rot)
end})
RB.vhk = true
return
end
end
end
end)
return RB.vhk
end
function RB.sendView(pitch, yaw)
if RB.camRem == nil then
local ok, r = pcall(function() return game:GetService("ReplicatedStorage").Remotes.Replication.Fighter.UpdateCameraRotation end)
RB.camRem = ok and r or false
end
if RB.camRem then pcall(RB.camRem.FireServer, RB.camRem, RB.encRot(Vector2.new(pitch, yaw)), nil) end
end

local function step(dt)
if RB.dead then return end
local ch = player.Character
local hum = ch and ch:FindFirstChildOfClass("Humanoid")
local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
local cam = Workspace.CurrentCamera
if not (rbActive() and hum and hrp and hum.Health > 0 and cam) then resetTarget(); RB.lastCF = nil; RB.viewOn = false; physSync(false); return end
physSync(true)
RB.viewOn = false
local t = pickTarget(hum, hrp)
local now = os.clock()
if RB.dmgHum then
local h0 = RB.dmgHum.Health
local d = RB.dmgLast - h0
if d > 0 then RB.dmgAcc = RB.dmgAcc + d end
RB.dmgLast = h0
if h0 <= 0 then RB.dmgHum = nil end
end
if t and RB.dmgHum ~= t.hum then RB.dmgHum = t.hum; RB.dmgLast = t.hum.Health end
if not (SA.rawFire and SA.useItem and SA.toEnum) and not SA.installing then task.spawn(function() SA.install(true) end) end
if t then
if RB.tgtPlr ~= t.plr then RB.tgtPlr = t.plr; RB.since = now end
RB.tgt = t
else resetTarget() end
local plan
local base = nil
if t then base = shootBase(t, now) end
local ready = false
local forcePark = false
if t and RB.watch then
local me = t.head.Position
local wl
for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
if p ~= player then
local hd = p.Character and p.Character:FindFirstChild("Head")
if hd then
local d = me - hd.Position
local m = d.Magnitude
if m > 0.1 and m <= RB.watchRange and hd.CFrame.LookVector:Dot(d / m) >= math.cos(math.rad(RB.watchAngle)) then wl = hd.CFrame.LookVector; break end
end
end
end
if wl then
if RB.watchMode == "Far Away" then forcePark = true; base = nil
else
local side = wl:Cross(Vector3.yAxis).Unit
if math.floor(os.clock() * 5) % 2 == 0 then side = -side end
base = CFrame.new(t.head.Position + side * RB.watchSide + Vector3.new(0, 1.5, 0))
end
end
end
local fighter = myFighter()
local list = fighter and weaponList(fighter)
if RB.weapon == "Utility" and list and #RB.seq > 1 and utilsSpent(list) then RB.advance() end
local curWp = RB.weapon
if curWp == "Utility" and RB.utFb and #RB.seq <= 1 and list and utilsSpent(list) then
curWp = RB.utFbWp or "Primary"; RB.ut.phase = nil; RB.ut.w = nil
end
RB.curWp = curWp
local utilMode = curWp == "Utility"
local evCF
if utilMode then RB.atk = true; RB.noPark = false; RB.stay = false; RB.jumpTh = 3 else evCF = evadeCF(hrp, t, base) end
if forcePark then RB.atk = false; evCF = nil end
local posCF = evCF or base
local org = posCF and posCF.Position or nil
local function isSettled(pos)
local last = RB.lastCF
if not RB.posSince or not last or (pos - last.Position).Magnitude > RB.jumpTh then RB.posSince = now end
return now - RB.posSince >= RB.settle
end
if fighter then
local eq = rawget(fighter, "EquippedItem")
local eqId = type(eq) == "table" and type(rawget(eq, "Data")) == "table" and rawget(eq, "Data").ObjectID or nil
local chosen
for _, w in ipairs(list) do if w.slot == curWp then chosen = w; break end end
RB.wpReady = true; RB.dryOut = false
if not chosen and not utilMode and #RB.seq > 1 and #list > 0 then
RB.missAt = RB.missAt or now
if now - RB.missAt > 0.4 then RB.advance() end
else RB.missAt = nil end
if utilMode then
evCF = nil
plan = RB.utilStep(fighter, list, eqId, t, hrp, cam, now)
ready = plan ~= nil
elseif chosen then
if eqId ~= chosen.id then RB.wpReady = false; RB.eqSeen = nil elseif RB.eqSeen ~= chosen.id then RB.eqSeen = chosen.id; RB.eqAt = now end
if eqId ~= chosen.id then
equip(chosen)
elseif t and now - RB.since >= RB.stab and now - RB.eqAt >= RB.eqWait then
if chosen.ty == "Melee" then
if t.dist <= (RB.kr and RB.krReach or 400) then
ready = tick() < RB.hitUntil or tick() >= RB.nextMelee
RB.wpReady = ready
local rp = t.root.Position
if RB.mPred then rp = rp + t.root.AssemblyLinearVelocity * math.min(dt * 2, 0.1) end
local rc = t.root.CFrame
local pos
if RB.mPos == "Inside" then pos = t.head.Position + Vector3.new(0, -0.7, 0.05)
elseif RB.kr then pos = rp - rc.LookVector * RB.mRange
elseif RB.mPos == "Front" then pos = rp + rc.LookVector * RB.mRange
elseif RB.mPos == "Above" then pos = rp + Vector3.new(0, RB.mRange + 1, 0)
elseif RB.mPos == "On Target" then pos = rp
elseif RB.mPos == "Sink" then pos = rp - Vector3.new(0, RB.mRange + 2, 0)
else pos = rp - rc.LookVector * RB.mRange end
if RB.kr then plan = CFrame.lookAt(pos, pos + rc.LookVector)
elseif RB.mFace then plan = CFrame.lookAt(pos, t.root.Position) else plan = CFrame.new(pos) end
evCF = nil
if RB.kr and chosen.name == "Knife" then
local rx, ry = rc:ToOrientation()
pcall(RB.viewHook)
RB.viewOn = true
RB.sendView(rx, ry)
end
if isSettled(plan.Position) then
for i = 1, ((RB.kr and chosen.name ~= "Knife") and RB.krSwings or 1) do
if i > 1 then RB.nextMelee = 0 end
if attackMelee(chosen, t, cam, plan.Position) then RB.shotAt = now; RB.cycDone = true end
end
end
end
elseif type(chosen.ammo) == "number" and chosen.ammo <= 0 then
RB.wpReady = false
if type(chosen.reserve) ~= "number" or chosen.reserve > 0 then
if reload(chosen) then RB.cycDone = true end
else RB.dryOut = true end
else
local cd = rawget(chosen.item, "_shoot_cooldown")
if type(cd) ~= "number" then cd = 0 end
RB.wpReady = tick() >= cd and tick() >= RB.nextShot
if RB.atk and tick() >= cd and tick() >= RB.nextShot then
ready = true
if isSettled(org or hrp.Position) then
RB.lockUntil = now + RB.hold
RB.shotAt = now
RB.spRoll = now + RB.hold
RB.nextShot = tick() + RB.fireGap
for _ = 1, RB.multi do fireGun(chosen, t, cam, org) end
end
end
end
end
end
end
if #RB.seq > 1 then
local U = RB.ut
if not (U and U.phase) then
local mode = RB.swm[RB.weapon] or "Reload"
if RB.dryOut or (mode == "Damage" and RB.dmgAcc >= (RB.swd[RB.weapon] or 100)) or (mode ~= "Damage" and RB.cycDone) then
RB.advance()
end
end
end
if RB.stay then plan = nil end
local cf = plan or posCF
if utilMode and t and not plan and not forcePark then
cf = RB.voidPos(t.head.Position - Vector3.new(0, RB.vsDepth, 0))
elseif t and ((RB.park and not RB.noPark and not ready and now >= RB.lockUntil) or forcePark) then
cf = CFrame.new(math.random(-1000000, 1000000), math.random(5000, 10000), math.random(-1000000, 1000000))
end
RB.lastCF = cf
if cf then
if not RB.oldCF then RB.oldCF = hrp.CFrame end
RB.root = hrp
hrp.CFrame = cf
end
end
local function restore()
if RB.oldCF and RB.root and RB.root.Parent then RB.root.CFrame = RB.oldCF end
RB.oldCF = nil
end
pcall(function() RunService:UnbindFromRenderStep("AspenRageRestore") end)
RunService:BindToRenderStep("AspenRageRestore", Enum.RenderPriority.First.Value, function() pcall(restore) end)
local hb = RunService.Heartbeat:Connect(function(dt) pcall(step, dt) end)
gui.Destroying:Connect(function()
RB.dead = true; RB.on = false
pcall(physSync, false)
pcall(function() hb:Disconnect() end)
pcall(restore)
pcall(function() RunService:UnbindFromRenderStep("AspenRageRestore") end)
end)
end)() end



do (function()
local wmod = addSub(mCombat, "Weapon Mods", "Aim & fire, cooldowns, melee and grenade modifiers.")
local M = {fire = false, firePct = 25, aim = false, aimPct = 200, aimCd = false, aimCdPct = 50, melee = false, meleePct = 25, dash = false, dashPct = 25,
rec = false, recPct = 75, auto = false, jumps = false, spread = false, fuse = false, fuseOn = "Impact", noFuse = false}
local orig = setmetatable({}, {__mode = "k"})
local eqHook = setmetatable({}, {__mode = "k"})
local function anyOn() return M.fire or M.aim or M.melee or M.dash or M.rec or M.auto or M.jumps end
local function put(info, o, k, v)
if rawget(info, k) == nil then return end
if o[k] == nil then o[k] = {rawget(info, k)} end
rawset(info, k, v)
end
local function back(info, o, k)
if o[k] then pcall(rawset, info, k, o[k][1]); o[k] = nil end
end
local function applyInfo(it)
local info = rawget(it, "Info")
if type(info) ~= "table" then return end
local o = orig[it]
if not o then o = {}; orig[it] = o end
local function bv(k) if o[k] ~= nil then return o[k][1] end return rawget(info, k) end
if M.fire and type(bv("ShootCooldown")) == "number" then put(info, o, "ShootCooldown", bv("ShootCooldown") * M.firePct / 100) else back(info, o, "ShootCooldown") end
if M.aim and type(bv("AimSpeed")) == "number" then put(info, o, "AimSpeed", bv("AimSpeed") * M.aimPct / 100) else back(info, o, "AimSpeed") end
if M.melee and type(bv("AttackCooldown")) == "number" then put(info, o, "AttackCooldown", bv("AttackCooldown") * M.meleePct / 100) else back(info, o, "AttackCooldown") end
if M.dash and type(bv("DashCooldown")) == "number" then put(info, o, "DashCooldown", bv("DashCooldown") * M.dashPct / 100) else back(info, o, "DashCooldown") end
if M.rec and type(bv("ShootRecoil")) == "number" then put(info, o, "ShootRecoil", bv("ShootRecoil") * (1 - M.recPct / 100)) else back(info, o, "ShootRecoil") end
if M.auto and type(bv("InputSpammingEnabled")) == "table" then
local c = table.clone(bv("InputSpammingEnabled")); c.StartShooting = 0; c.StartReloading = 0
put(info, o, "InputSpammingEnabled", c)
else back(info, o, "InputSpammingEnabled") end
if M.jumps and bv("MaxDoubleJumps") ~= nil then put(info, o, "MaxDoubleJumps", 676767) else back(info, o, "MaxDoubleJumps") end
end

local function hookEquip(it)
if eqHook[it] then return end
local mt = getmetatable(it)
local idx = mt and rawget(mt, "__index")
if type(idx) ~= "table" then return end
local st = {real = rawget(it, "_equip_cooldown"), scaled = rawget(it, "_equip_cooldown"), old = mt}
eqHook[it] = st
setmetatable(it, {
__index = function(t, k)
if k == "_equip_cooldown" then
local nm = debug and debug.info and debug.info(3, "n")
if M.aimCd and nm == "StartAiming" then return st.scaled end
return st.real
end
return idx[k]
end,
__newindex = function(t, k, v)
if k == "_equip_cooldown" then
local n = tick()
if type(v) == "number" then st.scaled = n + (v - n) * (M.aimCdPct / 100) else st.scaled = v end
st.real = v
return
end
rawset(t, k, v)
end,
})
rawset(it, "_equip_cooldown", nil)
end
local function unhookEquip(it)
local st = eqHook[it]
if not st then return end
pcall(setmetatable, it, st.old)
pcall(rawset, it, "_equip_cooldown", st.real)
eqHook[it] = nil
end
local function sweep()
local f = Core.myFighter and Core.myFighter()
if not f then return end
local its = rawget(f, "Items")
if type(its) ~= "table" then return end
for _, it in pairs(its) do
if type(it) == "table" then
pcall(applyInfo, it)
if M.aimCd then pcall(hookEquip, it) else pcall(unhookEquip, it) end
end
end
end
task.spawn(function()
local wasOn = false
while not Core.unloaded do
task.wait(0.2)
local on = anyOn() or M.aimCd
if on or wasOn then pcall(sweep) end
wasOn = on
end
end)

local function gget2(t, k)
if type(t) ~= "table" then return nil end
local v = rawget(t, k)
if v ~= nil then return v end
local ok, r = pcall(function() return t[k] end)
return ok and r or nil
end
M.tv = setmetatable({}, {__mode = "k"})
local function fuseImpact(tv)
local la = gget2(tv, "_last_args")
local step = type(la) == "table" and la[4] or 0.05
local mx = type(la) == "table" and la[6] or math.huge
local sph, segs = gget2(tv, "_impact_sphere"), gget2(tv, "_segments")
if not sph or type(segs) ~= "table" then return nil end
local cf = sph.CFrame
for k, s in pairs(segs) do
if s.CFrame == cf then return math.min(mx, (k - 2) * step) end
end
return nil
end
local throwMod, noFuseConst
local function setNoFuse(on)
if on and not noFuseConst then
local ok, m = pcall(function() return require(game:GetService("ReplicatedStorage").Modules.ItemTypes.Throwable) end)
if ok and type(m) == "table" then throwMod = m end
local fn = throwMod and (rawget(throwMod, "_StartThrow") or throwMod._StartThrow)
if type(fn) == "function" and debug.getconstants and debug.setconstant then
local okc, cs = pcall(debug.getconstants, fn)
if okc then
for i, c in pairs(cs) do
if c == "_cook_detonate_delay" then
if pcall(debug.setconstant, fn, i, "\0") then noFuseConst = {fn = fn, i = i} end
break
end
end
end
end
elseif not on and noFuseConst then
pcall(debug.setconstant, noFuseConst.fn, noFuseConst.i, "_cook_detonate_delay")
noFuseConst = nil
end
end
SA.mods = function(objId, encType, args)
local fe = SA.fromEnum
local nm = fe and rawget(fe, encType)
if not nm or type(args) ~= "table" then return end
local f = Core.myFighter and Core.myFighter()
local its = f and rawget(f, "Items")
local it
if type(its) == "table" then
for _, x in pairs(its) do
local d = type(x) == "table" and rawget(x, "Data")
if type(d) == "table" and d.ObjectID == objId then it = x; break end
end
end
local info = it and rawget(it, "Info")
local ty = type(info) == "table" and info.Type or nil
if SA.tracer and nm == "StartShooting" and ty ~= "Melee" and ty ~= "Throwable" then pcall(SA.tracer, args) end
if M.spread and nm == "StartShooting" and ty ~= nil and ty ~= "Melee" and ty ~= "Throwable" then args["\2"] = true end
if (ty == "Throwable" or gget2(it, "__type") == "Throwable") and gget2(info, "CanCook") then
if nm == "StartShooting" or nm == "StartAiming" then
if M.fuse then M.tv[it] = gget2(it, "_trajectory_visual") end
if M.noFuse then pcall(rawset, it, "_cook_detonate_delay", nil) end
elseif M.fuse and (nm == "FinishShooting" or nm == "FinishAiming") then
if M.fuseOn == "Throw" then args["\3"] = 0
else
local tv = M.tv[it]
local t = tv and fuseImpact(tv)
if t then args["\3"] = t end
end
M.tv[it] = nil
end
end
end
