local cf = cfDec(sh["\0"])
local cam = Workspace.CurrentCamera
if not cf or not cam then return end
trRP.FilterDescendantsInstances = {player.Character, cam}
local o, d = cf.Position, cf.LookVector * 1000
local r = Workspace:Raycast(o, d, trRP)
local e = r and r.Position or (o + d)
local len = (e - o).Magnitude
if len < 1 then return end
local p = Instance.new("Part")
p.Anchored = true; p.CanCollide = false; p.CanQuery = false; p.CanTouch = false; p.CastShadow = false
p.Material = W.trGlow and Enum.Material.Neon or Enum.Material.SmoothPlastic
p.Color = W.trCol
p.Size = Vector3.new(W.trW, W.trW, len)
p.CFrame = CFrame.lookAt(o, e) * CFrame.new(0, 0, -len / 2)
p.Parent = cam
local life, fade = W.trLife, W.trFade
task.delay(math.max(0, life - fade), function()
pcall(function() TweenService:Create(p, TweenInfo.new(fade), {Transparency = 1}):Play() end)
end)
task.delay(life, function() pcall(function() p:Destroy() end) end)
end

