end
local function hookAnimators(m)
for _, d in ipairs(m:GetDescendants()) do
if (d:IsA("Animator") or d:IsA("AnimationController")) and not animHooked[d] then
animHooked[d] = true
local an = d:IsA("Animator") and d or d:FindFirstChildOfClass("Animator")
