local function gget(t, k)
if type(t) ~= "table" then return nil end
local v = rawget(t, k)
if v ~= nil then return v end
local ok, r = pcall(function() return t[k] end)
return ok and r or nil
end
local vmaMod, vmaHooked
local STUB = {Play = function() end, Stop = function() end, Destroy = function() end}
local function vmaSuppress(self, name)
if type(name) ~= "string" then return false end
if W.noSprint and name == gget(self, "_sprint_animation") then return true end
if W.noEquip and name == gget(self, "_equip_animation") then return true end
if W.noShoot and (name:find("Shoot", 1, true) or name == "QuickShot") then return true end
if W.noReload and name:find("Reload", 1, true) then return true end
return false
end
local function vmaIsLocal(self)
local ok, r = pcall(function()
local cvm = gget(self, "ClientViewModel")
local ci = gget(cvm, "ClientItem")
local cf = gget(ci, "ClientFighter")
return gget(cf, "IsLocalPlayer")
end)
return ok and r ~= false
end
local function installVMA()
if vmaHooked then return end
if not vmaMod then
local ok, m = pcall(function()
return require(player.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem.ClientViewModel.ViewModelAnimator)
end)
if ok and type(m) == "table" then vmaMod = m end
end
if not vmaMod then return end
local orig = rawget(vmaMod, "PlayAnimation") or vmaMod.PlayAnimation
if type(orig) ~= "function" then return end
pcall(function() if setreadonly then setreadonly(vmaMod, false) end end)
local ok = pcall(rawset, vmaMod, "PlayAnimation", function(self, name, ...)
if (W.noShoot or W.noSprint or W.noEquip or W.noReload) and vmaSuppress(self, name) and vmaIsLocal(self) then
local tracks = gget(self, "_animation_tracks")
local tr = type(tracks) == "table" and tracks[name]
if tr then
tracks[name] = STUB
local ok2, e = pcall(orig, self, name, ...)
tracks[name] = tr
if not ok2 then error(e, 0) end
return
end
end
return orig(self, name, ...)
end)
if ok then vmaHooked = true end
end
