local wireMeshes, wireState = {}, setmetatable({}, {__mode = "k"})
local function withId(fn)
local old = getthreadidentity and getthreadidentity()
if setthreadidentity then pcall(setthreadidentity, 8) end
local ok, r = pcall(fn)
if old and setthreadidentity then pcall(setthreadidentity, old) end
return ok, r
end
local function buildWire(meshId, width, crease)
local key = meshId .. "|" .. string.format("%.5f", width) .. "|" .. crease
if wireMeshes[key] ~= nil then return wireMeshes[key] end
local res = false
withId(function()
local UGC = game:GetService("UGCValidationService")
if cloneref then UGC = cloneref(UGC) end
local okB, bin = pcall(UGC.GetMeshDataBinaryString, UGC, meshId)
if not okB then return end
local okE, em = pcall(UGC.CreateEditableMeshFromBinaryStringRobloxOnly, UGC, bin)
if not okE or not em then return end
local faces = {}
for _, f in ipairs(em:GetFaces()) do
local fv = em:GetFaceVertices(f)
if #fv >= 3 then
local ps = {}
for k, v in ipairs(fv) do ps[k] = em:GetPosition(v) end
local n = (ps[2] - ps[1]):Cross(ps[3] - ps[1])
if n.Magnitude >= 1e-6 then faces[#faces + 1] = {id = f, verts = fv, pos = ps, normal = n.Unit} end
end
end
for _, f in ipairs(faces) do em:RemoveFace(f.id) end
pcall(function() em:RemoveUnused() end)
local function pk(v) return ("%.3f,%.3f,%.3f"):format(v.X, v.Y, v.Z) end
local edgeMap, edges = {}, {}
for _, f in ipairs(faces) do
local n = #f.verts
for i = 1, n do
local j = i % n + 1
local a, b = f.pos[i], f.pos[j]
local ka, kb = pk(a), pk(b)
local key = ka .. "|" .. kb
if kb < ka then key = kb .. "|" .. ka end
local e = edgeMap[key]
if not e then
e = {a = a, b = b, normal = f.normal}
edgeMap[key] = e; edges[#edges + 1] = e
elseif e.opp == nil then e.opp = f.normal end
end
end
local function dotOf(e) return e.opp and e.normal:Dot(e.opp) or -1 end
local cosC = math.cos(math.rad(crease))
local keep = {}
for _, e in ipairs(edges) do if dotOf(e) < cosC then keep[#keep + 1] = e end end
if #keep > 10000 then
table.sort(keep, function(x, y) return dotOf(x) < dotOf(y) end)
for i = #keep, 10001, -1 do keep[i] = nil end
end
if #keep == 0 then return end
local hw = width * 0.5
for _, e in ipairs(keep) do
local d = e.b - e.a
if d.Magnitude >= 1e-6 then
local side = e.normal:Cross(d.Unit)
if side.Magnitude >= 1e-6 then
local u = side.Unit
local off = e.normal * 0.001
local okT = pcall(function()
local v1 = em:AddVertex(e.a - u * hw + off)
local v2 = em:AddVertex(e.a + u * hw + off)
local v3 = em:AddVertex(e.b + u * hw + off)
local v4 = em:AddVertex(e.b - u * hw + off)
for _ = 1, 4 do pcall(function() em:AddColor(Color3.new(1, 1, 1), 1) end) end
em:AddTriangle(v1, v2, v3)
em:AddTriangle(v1, v3, v4)
end)
if not okT then break end
end
end
end
res = Content.fromObject(em)
end)
wireMeshes[key] = res
return res
end
local function partRatio(p)
local ms, s, n, c = p.MeshSize, p.Size, 0, 0
for _, pr in ipairs({{ms.X, s.X}, {ms.Y, s.Y}, {ms.Z, s.Z}}) do
if pr[2] > 1e-6 then n = n + (pr[1] / pr[2]); c = c + (1) end
end
return c == 0 and 1 or n / c
end
local function isArmPart(p)
local n = p.Name:lower()
if n:find("arm") or n:find("hand") or n:find("glove") or n:find("sleeve") or n:find("finger") then return true end
local a = p.Parent
while a and a ~= workspace.CurrentCamera do
local an = a.Name:lower()
if an:find("arm") or an:find("hand") or an:find("glove") then return true end
a = a.Parent
end
return false
end
local function wireRestore(p, st)
wireState[p] = nil
pcall(function()
withId(function()
if st.content ~= nil then p.MeshContent = st.content end
p.Color = st.color
p.TextureID = st.tex
end)
end)
end
local function wireApply(p)
local st = wireState[p]
if st and st.busy then return end
if not st then
local okM, mc = pcall(function() return p.MeshContent end)
st = {content = okM and mc or nil, color = p.Color, tex = p.TextureID, meshId = p.MeshId, busy = true}
wireState[p] = st
else st.busy = true end
task.spawn(function()
local ok, content = pcall(buildWire, st.meshId, W.wireW * partRatio(p), 30)
if wireState[p] == st then
if ok and content then
withId(function() p.MeshContent = content; p.Color = W.wireCol; p.TextureID = "" end)
end
st.ver = W.wireVer
end
st.busy = false
end)
end
local wireNext = 0
local function wireStep(m)
if os.clock() < wireNext then return end
wireNext = os.clock() + 0.25
local anyOn = W.wireArms or W.wireItem
if not anyOn and next(wireState) == nil then return end
for _, p in ipairs(m:GetDescendants()) do
if p:IsA("MeshPart") and p.MeshId ~= "" then
local want = isArmPart(p) and W.wireArms or (not isArmPart(p) and W.wireItem)
local st = wireState[p]
if want then
if not st or (st.ver ~= W.wireVer and not st.busy) then pcall(wireApply, p)
elseif not st.busy then
pcall(function() withId(function() p.Color = W.wireCol end) end)
end
elseif st and not st.busy then
wireRestore(p, st)
end
end
end
end

local function wvFrame()
local cam = Workspace.CurrentCamera
if not cam then return end
local m = findVM(cam)
if W.noShake or W.noSway then
local x, y = cam.CFrame:ToOrientation()
cam.CFrame = CFrame.new(cam.CFrame.Position) * CFrame.fromOrientation(x, y, 0)
end
if m then
if W.noShoot or W.noSprint or W.noEquip or W.noReload or W.noMotion then pcall(installVMA); pcall(hookAnimators, m) end
local piv = m:GetPivot()
if vmModel ~= m then vmModel, vmBase, vmApplied = m, nil, nil end
if vmApplied and piv:FuzzyEq(vmApplied, 1e-4) then piv = vmBase end
if W.vm then
vmBase = piv
vmApplied = piv * CFrame.new(W.x, W.y, W.z) * CFrame.Angles(math.rad(W.p), math.rad(W.yw), math.rad(W.r))
m:PivotTo(vmApplied)
elseif vmApplied then
m:PivotTo(vmBase); vmApplied = nil
end
pcall(wireStep, m)
end
end
