local tpRP = RaycastParams.new()
tpRP.FilterType = Enum.RaycastFilterType.Exclude
local function tpFrame()
if not TP.on then return end
local cam = Workspace.CurrentCamera
if not cam then return end
local base = cam.CFrame
local goal = base * CFrame.new(TP.x, TP.y, TP.z)
if TP.ray then
tpRP.FilterDescendantsInstances = {player.Character, cam}
local dir = goal.Position - base.Position
local r = Workspace:Raycast(base.Position, dir, tpRP)
if r then goal = CFrame.new(base.Position + dir.Unit * math.max(0.5, (r.Position - base.Position).Magnitude - 0.4)) * (base - base.Position) end
end
cam.CFrame = goal
end
