local chState = setmetatable({}, {__mode = "k"})
local function chStrip(p, st, strip)
if strip and not st.stripped then
st.stripped = true
if p:IsA("MeshPart") then st.tex = p.TextureID; p.TextureID = "" end
st.hid = {}
for _, c in ipairs(p:GetChildren()) do
if c:IsA("Decal") or c:IsA("Texture") then st.hid[#st.hid + 1] = {c, "t", c.Transparency}; c.Transparency = 1
elseif c:IsA("SurfaceAppearance") then st.hid[#st.hid + 1] = {c, "p", c.Parent}; c.Parent = nil end
end
elseif not strip and st.stripped then
st.stripped = false
if st.tex ~= nil and p:IsA("MeshPart") then p.TextureID = st.tex end
for _, h in ipairs(st.hid or {}) do
if h[2] == "t" then h[1].Transparency = h[3] else h[1].Parent = h[3] end
end
st.hid = nil
end
end
local function chamsRestore(p, st)
chState[p] = nil
pcall(function()
chStrip(p, st, false)
p.Material = st.mat; p.Color = st.col; p.Transparency = st.tr; p.Reflectance = st.refl
end)
end
local chNext, hlObj = 0, nil
local function chamsStep(m)
if os.clock() < chNext then return end
chNext = os.clock() + 0.1
if not (CHM.arms.on or CHM.item.on) and next(chState) == nil then return end
for _, p in ipairs(m:GetDescendants()) do
if p:IsA("BasePart") then
local c = isArmPart(p) and CHM.arms or CHM.item
local st = chState[p]
if c.on and not wireState[p] then
if not st then st = {mat = p.Material, col = p.Color, tr = p.Transparency, refl = p.Reflectance}; chState[p] = st end
if st.tr < 1 then
local mat = Enum.Material[c.mat]
if mat and p.Material ~= mat then p.Material = mat end
if p.Color ~= c.col then p.Color = c.col end
if p.Transparency ~= c.tr then p.Transparency = c.tr end
end
pcall(chStrip, p, st, c.strip)
elseif st then chamsRestore(p, st) end
end
end
end
local function hlStep(m)
if HL.on and m then
if not hlObj or not hlObj.Parent then
hlObj = Instance.new("Highlight"); hlObj.Name = "AspenVMHighlight"; hlObj.Parent = Workspace.CurrentCamera
end
hlObj.Adornee = m; hlObj.Enabled = true
hlObj.FillColor = HL.fill; hlObj.FillTransparency = HL.fillT
hlObj.OutlineColor = HL.out; hlObj.OutlineTransparency = HL.outT
hlObj.DepthMode = HL.top and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded
elseif hlObj then hlObj.Enabled = false end
end
