for _, k in ipairs(faces) do if d[k] ~= nil then pcall(function() if sky[k] ~= d[k] then sky[k] = d[k] end end) end end
end
local function revert()
local sky = Lighting:FindFirstChildOfClass("Sky")
if sky and saved then for k, v in pairs(saved) do pcall(function() sky[k] = v end) end end
saved = nil
if mine and mine.Parent then mine:Destroy() end
mine = nil
end
