local function setP(o, k, v) pcall(function() o[k] = v end) end


local orig
local function capture()
    if orig then return end
    orig = {}
    for _, k in ipairs({"Brightness", "ExposureCompensation", "ShadowSoftness", "EnvironmentDiffuseScale", "EnvironmentSpecularScale", "GlobalShadows"}) do
        pcall(function() orig[k] = Lighting[k] end)
    end
end

local created = {}
local function fx(class, name)
    local o = Lighting:FindFirstChild(name)
    if o and o.ClassName == class then return o end
    o = Instance.new(class); o.Name = name; o.Parent = Lighting
    created[name] = o
    return o
end
local function kill(name)
    local o = Lighting:FindFirstChild(name); if o then o:Destroy() end
    created[name] = nil
end

local function applyRealism()
    if not W.on then
        if orig then for k, v in pairs(orig) do setP(Lighting, k, v) end end
        kill("AspenAtmos"); kill("AspenBloom"); kill("AspenCC"); kill("AspenDOF")
        return
    end
    capture()
    setP(Lighting, "Brightness", W.bright)
    setP(Lighting, "ExposureCompensation", W.exposure)
    setP(Lighting, "ShadowSoftness", W.shadowSoft)
    setP(Lighting, "EnvironmentDiffuseScale", W.diffuse)
    setP(Lighting, "EnvironmentSpecularScale", W.spec)
    setP(Lighting, "GlobalShadows", true)
    if W.atm then
        local a = fx("Atmosphere", "AspenAtmos")
        setP(a, "Density", W.atmDensity); setP(a, "Haze", W.atmHaze); setP(a, "Glare", W.atmGlare)
        setP(a, "Offset", 0.25); setP(a, "Color", Color3.fromRGB(199, 205, 215)); setP(a, "Decay", Color3.fromRGB(106, 112, 125))
    else kill("AspenAtmos") end
    if W.bloom then
        local b = fx("BloomEffect", "AspenBloom")
        setP(b, "Intensity", W.bloomI); setP(b, "Size", W.bloomSize); setP(b, "Threshold", 0.95)
    else kill("AspenBloom") end
    if W.cc then
        local c = fx("ColorCorrectionEffect", "AspenCC")
        setP(c, "Contrast", W.contrast); setP(c, "Saturation", W.sat)
    else kill("AspenCC") end
    if W.dof then
        local d = fx("DepthOfFieldEffect", "AspenDOF")
        setP(d, "FarIntensity", W.dofFar); setP(d, "NearIntensity", 0); setP(d, "FocusDistance", 70); setP(d, "InFocusRadius", 60)
    else kill("AspenDOF") end
end


